cd /workspace && python3 - <<'PYEOF'
import random, sys
sys.path.insert(0, '/workspace/submission')
import compiler

random.seed(0)
N = 48
PARTS = list(range(32)); ACC = list(range(32, 40)); CORE = list(range(40, 48))
links = []; seen = set()
def add(u, v):
    key = (min(u, v), max(u, v))
    if key in seen or u == v: return
    seen.add(key); links.append((u, v))
for p in PARTS:
    add(p, ACC[p % 8]); add(p, ACC[(p * 3 + 1) % 8])
for a in ACC:
    for c in CORE: add(a, c)
demands = {p: random.randrange(0, 6) for p in PARTS}
rate = 30; period = 4
envelope = {i: rate for i in range(len(links))}
caps = {l: period*rate for l in range(len(links))}
adj = compiler._adjacency(N, links, envelope)
ordinary = set(range(N)) - set(PARTS)
reach = {}
for u in PARTS:
    parent, _ = compiler._bfs_tree(adj, u, ordinary)
    reach[u] = [w for w in parent if w in PARTS and w != u]
trees, logical = compiler._logical_trees(PARTS, demands, reach, 'relay')
print('pairs', len(logical))
out = compiler._route(adj, ordinary, caps, logical, 0)
print('route ->', 'ok' if out else None, len(out) if out else '')
if out is None:
    # bisect: which pair fails
    residual = {}
    for l, c in caps.items():
        residual[(l, 0)] = c; residual[(l, 1)] = c
    items = sorted(logical.items(), key=lambda kv: (-kv[1], kv[0]))
    for idx, ((u, v), demand) in enumerate(items):
        need = demand
        ok = True
        while need > 0:
            chain = compiler._shortest_path(adj, u, v, ordinary, residual, need)
            if chain is None:
                chain, room = compiler._widest_path(adj, u, v, ordinary, residual)
                if chain is None:
                    print('fail at item', idx, (u, v), demand); ok = False; break
                take = min(need, room)
            else:
                take = min(need, min(residual[(l,d)] for l,d in chain))
            for l, d in chain:
                residual[(l,d)] -= take
            need -= take
        if not ok: break
PYEOF
